const regions=[{id:'california',name:'California, US',short:'California',lon:-120,lat:37,code:'01 / NORTH AMERICA',description:'Freight corridors, highway conditions, and the movement of a coast.',source:'Caltrans QuickMap',url:'https://quickmap.dot.ca.gov/',agent:'freight',label:'CALIFORNIA'},{id:'newyork',name:'New York, US',short:'New York',lon:-74,lat:41,code:'02 / NORTH AMERICA',description:'A proposed lens on urban traffic and the routes that connect a city.',source:'511 New York',url:'https://511ny.org/',agent:'city',label:'NEW YORK'},{id:'london',name:'London, UK',short:'London',lon:0,lat:52,code:'03 / EUROPE',description:'Street-level conditions across one of the world’s busiest cities.',source:'TfL traffic cameras',url:'https://tfl.gov.uk/info-for/open-data-users/',agent:'london',label:'LONDON'},{id:'singapore',name:'Singapore',short:'Singapore',lon:104,lat:1,code:'04 / SOUTHEAST ASIA',description:'A proposed mission covering port approaches and major expressways.',source:'Singapore data.gov.sg',url:'https://data.gov.sg/',agent:'port',label:'SINGAPORE'},{id:'tokyo',name:'Tokyo, Japan',short:'Tokyo',lon:140,lat:36,code:'05 / EAST ASIA',description:'A proposed city observation mission. Camera operators can contribute authorized coverage.',source:'Operator onboarding required',url:null,agent:'tokyo',label:'TOKYO'}];
const missions=[{id:'freight',name:'Freightwatch',ticker:'FREIGHT',region:'california',category:'freight',focus:'Freight',cost:4.8,color:'#e0eaca',ink:'#607345',symbol:'F',brief:'Watch I-5 for persistent freight queues. Corroborate changes with official incident reports.'},{id:'london',name:'London Lens',ticker:'LENS',region:'london',category:'cities',focus:'Urban traffic',cost:3.2,color:'#e4e6f0',ink:'#777d9c',symbol:'L',brief:'Observe traffic conditions at selected London intersections and flag persistent congestion.'},{id:'alpine',name:'Alpine Eye',ticker:'ALPINE',region:'california',category:'environment',focus:'Visibility',cost:2.4,color:'#dce9ed',ink:'#547c87',symbol:'A',brief:'Track visibility and snow conditions on selected Sierra Nevada road cameras.'},{id:'port',name:'Port Signal',ticker:'PORT',region:'singapore',category:'freight',focus:'Port approaches',cost:5.6,color:'#e9e5da',ink:'#9a845c',symbol:'P',brief:'Watch authorized cameras along port approaches for queues that persist across observations.'},{id:'city',name:'City Pulse',ticker:'PULSE',region:'newyork',category:'cities',focus:'Road conditions',cost:3.6,color:'#e8e1e9',ink:'#937e99',symbol:'C',brief:'Observe road congestion using appropriately licensed public traffic sources.'},{id:'tokyo',name:'Tokyo Observer',ticker:'TOKYO',region:'tokyo',category:'cities',focus:'City conditions',cost:4,color:'#eaded8',ink:'#a37864',symbol:'T',brief:'Build an operator-authorized camera mission for urban conditions in Tokyo.'}];
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let filter='all',selectedRegion='california',drafts=[];try{drafts=JSON.parse(localStorage.getItem('parallax-drafts')||'[]');if(!Array.isArray(drafts))drafts=[];drafts=drafts.filter(d=>d&&typeof d.name==='string'&&typeof d.ticker==='string'&&(regions.some(r=>r.id===d.region)||d.region==='finland')&&Number.isFinite(d.cost));}catch{drafts=[];}
function drawMap(){const land=$('#land');if(typeof WORLD_PATH!=='undefined')land.innerHTML=WORLD_PATH;$('#markers').innerHTML=regions.map((r,i)=>{const x=(r.lon+180)/360*1000,y=(90-r.lat)/180*470;return `<g class="marker" tabindex="0" role="button" aria-label="Select ${r.name}" data-region="${r.id}" transform="translate(${x},${y})"><circle class="pin-ring" r="${i===0?17:12}" fill="#9bbd6a15" stroke="${i===0?'#bfed82':'#788f61'}" stroke-width=".8"/><circle r="${i===0?4:3}" fill="${i===0?'#cdf5a0':'#9cbc75'}"/><text x="${i===1?15:0}" y="${i===1?4:-24}" text-anchor="${i===1?'start':'middle'}">${r.label}</text></g>`;}).join('');const center=[166,139];$('#routes').innerHTML=regions.slice(1).map(r=>{const x=(r.lon+180)/360*1000,y=(90-r.lat)/180*470;return `<path d="M${center[0]},${center[1]} Q${(center[0]+x)/2},${Math.min(y,center[1])-90} ${x},${y}"/>`;}).join('');$$('[data-region]').forEach(el=>{el.addEventListener('click',()=>selectRegion(el.dataset.region));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRegion(el.dataset.region);}});});}
function selectRegion(id){const r=regions.find(v=>v.id===id);if(!r)return;selectedRegion=id;$('#region-title').textContent=r.name;$('#region-panel .eyebrow').textContent='REGION '+r.code;$('#region-description').textContent=r.description;$('#source-name').textContent=r.source;$('#source-link').hidden=!r.url;if(r.url)$('#source-link').href=r.url;const m=missions.find(v=>v.id===r.agent);$('#region-agent').textContent=m.name;$('#region-ticker').textContent='$'+m.ticker+' · '+m.focus;$('#region-panel .mini-icon').textContent=m.symbol;$('#source-footnote').textContent=r.id==='tokyo'?'Planned coverage. No camera feed is connected for this region.':'Public viewing is available. Automated use and redistribution depend on source permissions.';$('#camera-image').hidden=true;$('#camera-fallback').hidden=false;$$('.marker').forEach(el=>{const active=el.dataset.region===id;el.querySelector('.pin-ring').setAttribute('stroke',active?'#d8ffb1':'#788f61');el.querySelector('.pin-ring').setAttribute('r',active?'17':'12');});}
function renderRows(){const query=$('#search').value.trim().toLowerCase();const list=[...drafts,...missions].filter(m=>(filter==='all'||filter==='drafts'&&m.draft||m.category===filter)&&[m.name,m.ticker,m.focus,regions.find(r=>r.id===m.region)?.short].join(' ').toLowerCase().includes(query));$('#mission-rows').innerHTML=list.map(m=>`<tr><td><button class="mission-title" data-mission="${escapeHtml(m.id)}"><span style="background:${m.draft?'#dde8d0':m.color};color:${m.draft?'#63724d':m.ink}">${escapeHtml(m.symbol||m.name[0])}</span><span><b>${escapeHtml(m.name)}</b><small>$${escapeHtml(m.ticker)}</small></span></button></td><td class="coverage">${escapeHtml(regions.find(r=>r.id===m.region)?.short||(m.region==='finland'?'Finland':'Custom'))}</td><td><span class="focus-tag">${escapeHtml(m.focus)}</span></td><td class="right compute">${m.costUnknown?"Variable":"$"+Number(m.cost).toFixed(2)}</td><td><span class="state"><i></i>${m.draft?'Draft':'Sample'}</span></td><td><button class="row-action" data-mission="${escapeHtml(m.id)}" aria-label="View ${escapeHtml(m.name)}">+</button></td></tr>`).join('');$('#table-count').textContent=String(list.length).padStart(2,'0');$('#mission-count').textContent=missions.length+drafts.length;$('#empty-state').hidden=!!list.length;$$('[data-mission]').forEach(b=>b.addEventListener('click',()=>openMission(b.dataset.mission)));}
function openInfo(kicker,html){$('#info-kicker').textContent=kicker;$('#info-body').innerHTML=html;$('#info-dialog').showModal();}
function openMission(id){const m=[...drafts,...missions].find(v=>v.id===id);if(!m)return;const region=regions.find(r=>r.id===m.region);openInfo('MISSION / $'+m.ticker,`<h2>${escapeHtml(m.name)}</h2><div class="evidence-header"><span class="pill">${m.draft?'LOCAL DRAFT':'SAMPLE MISSION'}</span><span class="pill">${escapeHtml(region.name)}</span></div><p>${escapeHtml(m.brief)}</p><div class="draft-meta"><div><span>ESTIMATED COMPUTE / DAY</span><b>$${Number(m.cost).toFixed(2)}</b></div><div><span>COIN STATUS</span><b>Not issued</b></div><div><span>OBSERVATION SOURCE</span><b>${escapeHtml(region.source)}</b></div><div><span>FEED CONNECTION</span><b>Not connected</b></div></div><div class="dialog-note">This is a mission concept. Camera access, inference, and onchain settlement are not active in this preview.</div><button class="button primary" id="use-mission">Use this mission brief</button>`);$('#use-mission').onclick=()=>{$('#info-dialog').close();openLaunch(m);};}
function openLaunch(seed){
  $('#launch-body').innerHTML=`<h2>Give your coin a mission.</h2><p>Choose what your agent observes. Its coin helps fund the work.</p><div class="dialog-note">Demo launch: saves a mission draft on this browser. No wallet transaction, payment, or coin issuance occurs.</div><form id="launch-form"><div class="form-grid"><label>Coin name<input name="name" required maxlength="40" placeholder="e.g. Freightwatch" value="${escapeHtml(seed?.name||'')}"></label><label>Ticker<input name="ticker" required pattern="[A-Za-z][A-Za-z0-9]{1,9}" maxlength="10" placeholder="e.g. FREIGHT" value="${escapeHtml(seed?.ticker||'')}"><small>2–10 letters or numbers, starting with a letter.</small></label><label class="full">Monitoring mission<textarea name="brief" required minlength="12" maxlength="500" placeholder="Watch this corridor. Alert me when a queue persists across three observations.">${escapeHtml(seed?.brief||'')}</textarea></label><label>Camera region<select name="region">${regions.map(r=>`<option value="${r.id}"${r.id===(seed?.region||selectedRegion)?' selected':''}>${r.name}</option>`).join('')}</select></label><label>Observation frequency<select name="interval"><option value="15">Every 15 minutes</option><option value="5" selected>Every 5 minutes</option><option value="1">Every minute</option></select></label><label>Number of cameras<input name="cameras" type="number" min="1" max="50" value="5" required></label><label>Initial compute budget (USD)<input name="budget" type="number" min="1" max="100000" value="100" step="1" required></label></div><div class="estimate"><div><span>OBSERVATIONS / DAY</span><b id="estimate-obs"></b></div><div><span>TOKEN COST / DAY</span><b id="estimate-day"></b></div><div><span>BUDGET RUNWAY</span><b id="estimate-runway"></b></div></div><small class="estimate-assumptions">Token-cost estimate: 1,500 input + 250 output tokens per observation at the selected model’s listed price. Image, audio, request, reasoning, tool, licensing, storage and network charges are excluded. Free models have limits. Proposed trading fee: 1.5%; 0.75% goes to compute.</small><div class="form-footer"><span>You own the mission. The agent does the observing.</span><button class="button primary" type="submit">Create demo mission</button></div><div class="error-text" id="form-error" role="alert"></div></form>`;
  $('#launch-dialog').showModal();const form=$('#launch-form');window.initLaunchModels?.(form,seed);window.initLaunchCamera?.(form,seed);
  const update=()=>{const data=new FormData(form),obs=1440/Number(data.get('interval'))*Number(data.get('cameras')),day=window.modelDailyEstimate?window.modelDailyEstimate(form,obs):obs*.002;$('#estimate-obs').textContent=Number.isFinite(obs)&&obs>0?Math.round(obs).toLocaleString():'—';$('#estimate-day').textContent=Number.isFinite(day)&&day>=0?'$'+day.toFixed(2):'Variable';$('#estimate-runway').textContent=day>0?Math.floor(Number(data.get('budget'))/day)+' days':day===0?'Free tier':'—';};
  form.addEventListener('input',update);update();
  form.onsubmit=e=>{e.preventDefault();if(window.validateLaunchCamera&&!window.validateLaunchCamera(form))return;const data=new FormData(form);const name=String(data.get('name')).trim(),ticker=String(data.get('ticker')).trim().toUpperCase(),brief=String(data.get('brief')).trim();if(name.length<2||brief.length<12){$('#form-error').textContent='Add a name with at least two characters and a mission of at least 12 characters.';return;}if([...drafts,...missions].some(m=>m.ticker===ticker)){$('#form-error').textContent='That ticker is already used in this demo. Choose another ticker.';return;}
    const d={id:'draft-'+Date.now(),name,ticker,brief,region:String(data.get('region')),cameras:Number(data.get('cameras')),interval:Number(data.get('interval')),budget:Number(data.get('budget')),cost:1440/Number(data.get('interval'))*Number(data.get('cameras'))*.002,draft:true,category:'drafts',focus:'Custom mission',symbol:name[0].toUpperCase(),...(window.draftModelMetadata?.(form)||{})};
    try{localStorage.setItem('parallax-drafts',JSON.stringify([d,...drafts]));}catch{$('#form-error').textContent='This browser could not save your draft. Allow local storage and try again.';return;}
    drafts.unshift(d);renderRows();$('#launch-body').innerHTML=`<div class="success-mark">✓</div><h2>Your mission has a home.</h2><p><b>${escapeHtml(d.name)}</b> / $${escapeHtml(d.ticker)} is saved as a local draft.</p><div class="draft-meta"><div><span>CAMERAS PLANNED</span><b>${d.cameras}</b></div><div><span>TOKEN COST / DAY</span><b>${d.costUnknown?'Variable':'$'+d.cost.toFixed(2)}</b></div><div><span>STARTING BUDGET</span><b>$${d.budget.toFixed(2)} (simulated)</b></div><div><span>STATUS</span><b>Draft · coin not issued</b></div><div class="full"><span>AGENT MODEL</span><b>${escapeHtml(d.modelName||d.modelId||'Not selected')}</b></div></div><div class="dialog-note">Open your mission to preview a connected camera and run the selected image model. Coin issuance and fee settlement require deployed contracts and a payment provider.</div><button class="button primary" id="view-drafts">View my drafts</button>`;$('#view-drafts').onclick=()=>{$('#launch-dialog').close();document.body.classList.remove('model-mode');if(document.body.classList.contains('token-mode')){exitToken();renderCameraDirectory();}setFilter('drafts');$('#explore').scrollIntoView({behavior:'smooth'});};
  };
}

function setFilter(v){filter=v;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===v));renderRows();}
function openHow(){openInfo('PARALLAX / HOW IT WORKS',`<h2>A coin that pays attention.</h2><p>A proposed funding loop for useful observations of the physical world.</p><div class="steps"><div class="dialog-section"><h3>Launch a mission coin</h3><p>Define a monitoring brief, choose authorized cameras, and set the compute budget. In this preview, the launch creates a local draft.</p></div><div class="dialog-section"><h3>Fund the observations</h3><p>The proposed 1.5% trading fee allocates 0.75% to agent compute, 0.50% to camera operators, and 0.25% to the protocol treasury. Upfront budgets cover periods with low trading activity.</p></div><div class="dialog-section"><h3>Check, compare, corroborate</h3><p>Check freshness and visibility first. Compare observations over time, then consult independent sources before publishing an alert.</p></div><div class="dialog-section"><h3>Keep the evidence</h3><p>Attach source timestamps, observations, uncertainty and corrections. An onchain hash could establish report history; it does not establish that a report is true.</p></div></div><div class="dialog-note">Current state: live camera playback and server-backed OpenRouter observations. Fee distribution, payments and coin contracts are not connected.</div>`);}
function openSources(){openInfo('PARALLAX / CAMERA SOURCES',`<h2>Permission is part of the network.</h2><p>Sources are shown for discovery. Public viewing, automated analysis and redistribution are separate permissions.</p><div class="source-list">${regions.map(r=>`<div class="dialog-section">${r.url?`<a href="${r.url}" target="_blank" rel="noopener">${escapeHtml(r.source)} · ${r.name} ↗</a>`:`<h3>${r.name} — planned operator coverage</h3>`}<small>${r.url?'Review current provider terms before connecting cameras to a commercial mission. Connected feeds can be previewed and analyzed in the observation workspace.':'No provider or camera access is claimed. Owner-authorized feeds would be onboarded for this region.'}</small></div>`).join('')}</div><p style="font-size:11px">Map geometry: Natural Earth (public domain). Interface inspired by Cradle; independent from Cradle and Palantir.</p>`);}
function openAlert(id){const alpine=id==='alpine';openInfo('INTELLIGENCE / EVIDENCE RECORD',`<h2>${alpine?'Visibility falling at the summit':'Queue persists on I-5'}</h2><div class="evidence-header"><span class="pill">SIMULATED RECORD</span><span class="pill">${alpine?'ALPINE EYE':'FREIGHTWATCH'}</span></div><p>${alpine?'A sample visibility change detected in two consecutive observations.':'A sample persistent queue, assembled from three observations of one corridor.'}</p><div class="dialog-note">Illustrative scenario. These observations are not measurements from a real camera and must not be used for travel decisions.</div>${(alpine?[['14:13 UTC','Visibility baseline','Roadway visible to the far side of the frame.'],['14:18 UTC','Change persists','Distant landmarks become obscured. Lighting or camera exposure could explain the change.']]:[['14:22 UTC','Queue first observed','A hypothetical queue is visible on the northbound approach.'],['14:27 UTC','Queue persists','The queue remains in the same road segment after five minutes.'],['14:32 UTC','Third observation','Continued congestion would trigger a request for corroboration.']]).map(r=>`<div class="evidence-record"><time>${r[0]}</time><h4>${r[1]}</h4><p>${r[2]}</p></div>`).join('')}<div class="dialog-section" style="margin-top:23px"><h3>Corroboration</h3><p>Not performed. Check official incidents, weather and adjacent cameras. A single camera cannot establish the cause of a disruption.</p></div><div class="dialog-section"><h3>Business exposure</h3><p>Affected route and delivery impact would remain unverified until linked to a customer’s actual operations.</p></div><a class="button" href="https://quickmap.dot.ca.gov/" target="_blank" rel="noopener">Open official road conditions</a>`);}
function openWallet(){openInfo('PARALLAX / WALLET',`<h2>Start with a mission.</h2><p>Wallet connection is not enabled in this concept. You can explore the network and create a demo mission without signing a transaction.</p><div class="dialog-note">No funds are collected. Coin deployment and compute payments need a selected blockchain, reviewed contracts, and a configured payment provider.</div><button class="button primary" id="wallet-launch">Create a demo mission</button>`);$('#wallet-launch').onclick=()=>{$('#info-dialog').close();openLaunch();};}
$$('[data-open]').forEach(b=>b.addEventListener('click',()=>({launch:openLaunch,how:openHow,sources:openSources,wallet:openWallet}[b.dataset.open])()));$$('[data-nav]').forEach(b=>b.onclick=()=>{$$('#'+b.dataset.nav)[0]?.scrollIntoView({behavior:'smooth'});$$('[data-nav]').forEach(n=>n.classList.toggle('active',n===b));});$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const rect=d.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)d.close();}}));$$('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));$('#search').addEventListener('input',renderRows);$$('[data-alert]').forEach(b=>b.onclick=()=>openAlert(b.dataset.alert));$('#region-details').onclick=()=>openMission(regions.find(r=>r.id===selectedRegion).agent);
regions.find(r=>r.id==='singapore').source='LTA OneMotoring';regions.find(r=>r.id==='singapore').url='https://onemotoring.lta.gov.sg/content/onemotoring/home/driving/traffic_information/traffic-cameras.html';
const snapshots={california:{url:'https://cwwp2.dot.ca.gov/data/d4/cctv/image/tvd32i80baybridgesastowereast/tvd32i80baybridgesastowereast.jpg',label:'Caltrans · Bay Bridge SAS Tower East',source:'https://cwwp2.dot.ca.gov/closed-circuit-television-cameras.html'},london:{url:'https://s3-eu-west-1.amazonaws.com/jamcams.tfl.gov.uk/00001.03500.jpg',label:'TfL · Tower Bridge / East Smithfield',source:'https://tfl.gov.uk/traffic/status'}};
let imageExpiry;const originalSelectRegion=selectRegion;selectRegion=function(id){originalSelectRegion(id);loadSnapshot(id);};
function loadSnapshot(id){clearTimeout(imageExpiry);const cam=snapshots[id],img=$('#camera-image'),fallback=$('#camera-fallback');img.onload=null;img.onerror=null;img.removeAttribute('src');$('#refresh-image')?.remove();if(!cam){$('.camera-overlay').textContent='DIRECTORY / NO CONNECTED ANALYSIS';return;}const requestedId=id;fallback.querySelector('span').textContent='Loading provider image…';img.alt=cam.label+'; current provider snapshot, not analyzed';img.onload=()=>{if(selectedRegion!==requestedId)return;img.hidden=false;fallback.hidden=true;};img.onerror=()=>{if(selectedRegion!==requestedId)return;img.hidden=true;fallback.hidden=false;fallback.querySelector('span').textContent='Image unavailable · open source';};img.src=cam.url;$('.camera-overlay').textContent='PROVIDER SNAPSHOT / ANALYSIS OFF';$('#source-name').textContent=cam.label;$('#source-link').href=cam.source;$('#source-footnote').innerHTML='Provider image; see its embedded capture time. No image analysis is running. <button id="refresh-image">Refresh image</button>';$('#refresh-image').onclick=()=>loadSnapshot(id);imageExpiry=setTimeout(()=>{if(selectedRegion!==requestedId)return;img.hidden=true;img.removeAttribute('src');fallback.hidden=false;fallback.querySelector('span').textContent='Refresh to view a recent image';$('.camera-overlay').textContent='IMAGE HIDDEN AFTER 5 MINUTES';},300000);}
$('#world-map').setAttribute('role','group');
$('#source-grid').innerHTML=regions.slice(0,4).map(r=>`<button class="source-tile" data-source-region="${r.id}"><span>PUBLIC DIRECTORY / ${r.short.toUpperCase()}</span><b>${r.source}</b><span>Select to inspect source</span></button>`).join('');$$('[data-source-region]').forEach(b=>b.onclick=()=>selectRegion(b.dataset.sourceRegion));$('#feed-view').onclick=()=>{$('#source-grid').hidden=false;$('#feed-view').classList.add('active');$('#map-view').classList.remove('active');};$('#map-view').onclick=()=>{$('#source-grid').hidden=true;$('#map-view').classList.add('active');$('#feed-view').classList.remove('active');};drawMap();renderRows();originalSelectRegion('california');
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const specs=[{name:'parallax_list_missions',title:'List mission concepts',description:'Read sample missions and local drafts, and coin issuance status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {missions:[...drafts,...missions].map(m=>({name:m.name,ticker:m.ticker,region:m.region,status:m.draft?'local_draft':'sample',coinIssued:false,feedConnected:["california","london"].includes(m.region)}))};}},{name:'parallax_select_region',title:'Inspect a camera region',description:'Select a region and show its connected camera, when available.',inputSchema:{type:'object',properties:{region:{type:'string',enum:regions.map(r=>r.id)}},required:['region'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!regions.some(r=>r.id===input.region)||Object.keys(input).some(k=>k!=='region'))throw new Error('Choose a supported region');selectRegion(input.region);return {selectedRegion,feedConnected:false};}}];for(const tool of specs){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
